// 仅明确新规程与原首职制度能启用辞任；缺模块的新来源/回执不能落回旧政治宽许可。
#include "political_office_resignation_profile.hpp"
#include "resident/domains/politics/succession/political_succession_profile.hpp"
#include "resident/domains/organization/organization_office_history.hpp"
namespace hanmo::resident {
bool is_political_office_resignation_fact_kind(const StableId& kind){return kind=="political_office_resignation_requested"||kind=="political_office_resignation_answered"||kind=="political_office_resignation_withdrawn";}
Outcome<Integer> political_office_resignation_selected_version(const std::vector<std::pair<StableId,StableId>>& modules){Integer version=0,origins=0;for(const auto& m:modules){if(m.first==political_office_resignation_module){if((m.second!="1"&&m.second!="2")||version)return {false,0,common_failure("PoliticalOfficeResignationModuleMismatch").error};version=m.second=="1"?1:2;}if(m.first==political_office_resignation_responses_module&&(m.second!="1"||++origins!=1))return {false,0,common_failure("OfficeResignationResponseModuleMismatch").error};}if((version==2)!=(origins==1))return {false,0,common_failure("OfficeResignationResponseVersionPairRequired").error};if(!version)return {true,0,{}};auto original=political_succession_selected_version(modules);if(!original.ok)return original;if(original.value!=1)return {false,0,common_failure("PoliticalOfficeResignationOriginalProfileRequired").error};return {true,version,{}};}
Outcome<std::optional<PoliticalOfficeResignationCatalog>> decode_political_office_resignation_profile(const BoundaryValue& scenario,const std::vector<StableId>& caps){const auto* dynamic=scenario.find("dynamic_world");const auto* group=dynamic?dynamic->find(political_office_resignation_module):nullptr;if(!group){auto responses=decode_political_office_resignation_response_profile(scenario,caps);return responses.ok?Outcome<std::optional<PoliticalOfficeResignationCatalog>>{true,std::nullopt,{}}:Outcome<std::optional<PoliticalOfficeResignationCatalog>>{false,{},responses.error};}auto old=decode_political_succession_profile(scenario,caps);if(!old.ok)return {false,{},old.error};if(!old.value)return {false,{},common_failure("PoliticalOfficeResignationOriginalProfileRequired").error};auto decoded=decode_political_office_resignation_catalog(*group);if(!decoded.ok)return {false,{},decoded.error};const auto cap=decoded.value.version==1?"political_office_resignations_v1":"political_office_resignations_v2";if(std::find(caps.begin(),caps.end(),cap)==caps.end())return {false,{},common_failure("PoliticalOfficeResignationCapabilityRequired").error};auto responses=decode_political_office_resignation_response_profile(scenario,caps);if(!responses.ok)return {false,{},responses.error};if(decoded.value.policies.empty()||decoded.value.policies.size()>4096)return {false,{},common_failure("InvalidPoliticalOfficeResignationCatalog").error};return {true,std::move(decoded.value),{}};}
Status validate_political_office_resignation_layout(const CommonStore& c,const std::vector<std::pair<StableId,StableId>>& modules,const PoliticalOfficeResignationState* state){auto version=political_office_resignation_selected_version(modules);if(!version.ok)return {false,{},version.error};if(bool(state)!=(version.value!=0)||(state&&state->version!=version.value))return common_failure("PoliticalOfficeResignationProfileMismatch");if(!state){for(const auto& row:c.state().facts.rows())if(is_political_office_resignation_fact_kind(row.second.kind)||row.second.domain==political_office_resignation_module)return common_failure("PoliticalOfficeResignationProfileRequired",row.first);for(const auto& row:c.state().results.rows())if(row.second&&is_political_office_resignation_command(row.second->kind))return common_failure("PoliticalOfficeResignationProfileRequired",row.first);for(const auto& h:c.state().history)if(is_political_office_resignation_command(h.kind))return common_failure("PoliticalOfficeResignationProfileRequired",h.result_id);}return common_success();}
Status validate_political_office_resignation_fact_header(const CommonStore& c,const PoliticalOfficeResignationState& state,const FactRecord& h){bool found=false;if(h.kind=="political_office_resignation_requested"){const auto* r=state.requests.find(h.id);found=r&&r->id==h.id;}else if(h.kind=="political_office_resignation_answered"){const auto* r=state.answers.find(h.id);found=r&&r->id==h.id;}else if(h.kind=="political_office_resignation_withdrawn"){const auto* r=state.withdrawals.find(h.id);found=r&&r->id==h.id;}return (state.version==1||state.version==2)&&found&&h.domain==political_office_resignation_module&&political_office_resignation_fact_sequence(c,h.id,h.kind)?common_success():common_failure("PoliticalOfficeResignationFactMismatch",h.id);}
// 独占业务前缀不能被旧政治kind伪装，格式识别本身并不授予权源。
bool political_office_resignation_effect_uses_sources(const PoliticsEffects& effect){for(const auto* ids:{&effect.fact_ids,&effect.receipt_ids})for(const auto& id:*ids)if(id.rfind("political_office_resignation_",0)==0)return true;return false;}
bool valid_political_office_resignation_effect(const StableId& kind,const PoliticsEffects& effect){if(!is_political_office_resignation_command(kind)||!effect.appointment_id.empty()||effect.fact_ids!=effect.receipt_ids||effect.fact_ids.empty()||effect.fact_ids.size()>2)return false;StableId prefix;if(kind==political_office_resignation_request_command)prefix="political_office_resignation_request";else if(kind==political_office_resignation_answer_command)prefix="political_office_resignation_answer";else prefix="political_office_resignation_withdrawal";auto source=organization_instance_sequence(effect.fact_ids.front(),prefix);if(!source)return false;if(effect.fact_ids.size()==1)return true;if(kind!=political_office_resignation_answer_command||*source==std::numeric_limits<Integer>::max())return false;auto office=organization_instance_sequence(effect.fact_ids.back(),"organization");return office&&*office==*source+1;}
}
